export function projectGermanyPoint(point: GeoPoint) {
  const x = (point.longitude * Math.PI) / 180;
  const y = Math.log(Math.tan(Math.PI / 4 + (point.latitude * Math.PI) / 360));
  return {
    x: 29.394811623134814 + (x - 0.10214521994004294) * 2756.8899329254973,
    y: 20 + (1.1562242154680291 - y) * 2756.8899329254973,
  };
}
